Create Payment Plan.code:
// Not supported: this adaptor (Flutterwave v4) has no payment plan function,
// and no generic request helper. It only exposes createCustomer,
// createPaymentMethod and initiatePayment.
// Closest option: charge one instalment as a one-off payment.
initiatePayment({
  // Amount in the currency's main unit.
  amount: 5000,
  currency: 'NGN',
  customer_id: $.data.customerId,
  payment_method_id: $.data.paymentMethodId,
  // Unique reference per instalment.
  reference: `plan-${$.data.memberId}-${$.data.instalment}`,
});

